'x_mo-definition'('x_ZEA--0015093',"&quot;The penultimate bract-like structure that subtends the upper (pedicelled) floret of the sessile spikelet of the ear (pistillate inflorescence). As part of the upper floret, the inner lemma is oriented in a position that is opposite the palea &amp; adjacent to the upper (inner) glume of the sessile spikelet. The lemma arises from the floret pedicel immediately below the palea.&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40e49).
xc_microtheory(a65b125bd40e49,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40e49,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd40e49,68).
xc_kb_names(a65b125bd40e49,[]).
xc_mapping_rows(a65b125bd40e49,[]).
'x_mo-definition'('x_ZEA--0015160',"&quot;Shoot meristematic tissue arising other than at the apex or in association with a leaf primordium. This is  the same meristem which gives rise to shoots, collectively called tillers. Observations indicate that while axillary buds may be involved in adventitious shoot growth (formation of tillers), several of these shoots (tillers) can arise from a single node. These observations suggest that the adventitious shoot meristem is recognizably distinct from the axillary bud meristem.&quot; [MaizeGDB:lv (ID# 165572)]") :- x_cid(a65b125bd40e4a).
xc_microtheory(a65b125bd40e4a,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40e4a,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd40e4a,70).
xc_kb_names(a65b125bd40e4a,[]).
xc_mapping_rows(a65b125bd40e4a,[]).
'x_mo-definition'('x_ZEA--0015061',"&quot;The primary root (radicle or tap root) is the initial root structure which emerges from the embryo of the caryopsis (kernel/seed). The primary root is formed early during embryogenesis, becoming defined as a distinctive region 10-15 days after pollination. The primary root is enclosed by a protective ensheathing structure, the coleorhiza. A variable number of adventitious lateral roots arise from the primary root (these are not formed during embryogenesis). See 'lateral root' for further information on lateral roots (seminal lateral roots). These lateral roots arise at varying points behind the zone of root hair formation on the primary root.  The primary root is always present (except when killed by some injury e.g. freezing).&quot; [MaizeGDB:lv, Feldman , in Freeling &amp; Walbot (eds) , The Maize Handbook , ID # 60920:< new dbxref>]") :- x_cid(a65b125bd40e4b).
xc_microtheory(a65b125bd40e4b,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40e4b,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd40e4b,72).
