'x_mo-definition'('x_ZEA--0015119',"&quot;Two, small, scale-like. pale-green structures (glandular-like organs) found adjacent to the inner surface of the base of the lemma of the floret. The adjacent margins of the two lodicules (opposite the mid-line of the lemma) are adpressed to each other while the inner surfaces of the lodicules form an angle of approximately 80 degrees to each other. Within the triangle of basal tissue, bounded on two sides by the two lodicules, are located the three filaments of the stamens. Just prior to anthesis the lodicules grow/swell laterally and the triangle of space between the lodicules is almost obscured. The two lodicules are thought to be involved in opening of the grass floret (flower) in readiness for pollination (at anthesis they grow/become increasingly turgid and are presumed to contribute to the displacing of the adjacent lemma and glume which facilitates the exsertion of the anthers for wind pollination). Gibbs Russell et al., Grasses of southern Africa, 1990; Ambrose et al., (2000), Molecular and Genetic Analyses of the Silky1 Gene Reveal Conservation in Floral Organ Specification between Eudicots and Monocots, Molecular Cell 5:569-579. Leszek Vincent 06/2000.&quot; [MaizeGDB:lv (ID# 165572)]") :- x_cid(a65b125bd40e63).
xc_microtheory(a65b125bd40e63,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40e63,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
