'x_mo-definition'('x_ZEA--0015083',"&quot;The attachment of the leaf to the node of the culm is via the base of the leaf sheath. The attachment of the leaf base is not in a circle but in a short spiral extending a little more than once around the culm (stem). The edge of the leaf which is attached lower on the culm (at a node) overlaps the other edge of the leaf which is attached to the culm slightly higher up. Note that the pattern of overlap alternates between successive leaves - each leaf  sheath is rolled around the culm in the opposite direction from that of the preceding leaf.&quot; [MaizeGDB:59445, MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40e80).
