'x_mo-definition'('x_ZEA--0015065',"&quot;These (adventitious) lateral roots  emerge from the primary root (radicle, tap root) at varying points behind the zone of root hair formation. They originate from the pericycle. They are not present during embyogenesis.&quot; [MaizeGDB:lv, Feldman in Freeling &amp; Walbot (eds) , 1994. The Maize Handbook , ID # 60920:< new dbxref>, Poethig in Sheridan , WF (ed) , 1982. Maize for Biological Research , ID # 25744:< new dbxref>]") :- x_cid(a65b125bd40e88).
