'x_mo-definition'('x_ZEA--0015169',"&quot;The meristem which gives rise to a root branch  (ZEA:15069). A root branch is an adventitious root that emerges from any of the various types of lateral root. Root branches arise at varying points behind (posterior to) the zone of root hair formation on the primary root. Root branches emerge from the surface of the main roots (the various types of lateral roots) at irregular intervals. When a root branches, the initial of each branch is formed from cells of the pericycle. Via cell division a bulging hemispherical mass of meristematic tissue is formed. The outer part of this forms the beginning of the rootcap, while the cells of the growing point are near the flat basal part of the hemispherical mass.&quot; [MaizeGDB:lv (ID# 165572)]") :- x_cid(a65b125bd40e8f).
xc_microtheory(a65b125bd40e8f,'x_zea_mays_anatomy-merged-SUMOMt').
