xc_source_line(a65b125bd40e8f,217).
xc_kb_names(a65b125bd40e8f,[]).
xc_mapping_rows(a65b125bd40e8f,[]).
'x_mo-definition'('x_ZEA--0015161',"&quot;A meristematic tissue consisting of parallel layers of cells dividing anticlinally (perpendicular to the leaf surface). The divisions in this meristem constitute a major part of the intercalary growth by which the leaf reaches its mature size (with respect to surface area; periclinal divisions are responsible for increasing leaf thickness). (Esau, ID#139825; Vincent ID#165572, 2002)&quot; [MaizeGDB:lv (ID# 165572), MaizeGDB:Esau (ID# 139825)]") :- x_cid(a65b125bd40e90).
