'x_mo-definition'('x_ZEA--0015138',"&quot;The androecium is the male reproductive whorl of a flowering plant, comprising the stamen(s). Each stamen of the androecium usually comprises of a  filament (stalk-like structure) and anther (pollen producing structure). In some taxa one or more of the stamens may be sterile (producing no pollen). These modified stamens are called staminodes.&quot; [MaizeGDB:275295, Allaby 1992:The Concise Oxford Dictionary of Botany, Esau 1977:Anatomy of Seed Plants, MaizeGDB:lv (ID # 165572), MaizeGDB:wiedemeier (ID # 292238)]") :- x_cid(a65b125bd40e97).
