'x_mo-definition'('x_ZEA--0015137',"&quot;A small rounded or scale-like structure (glandular-like organ) found between the base of the stamens in the grass floret (flower). The lodicules (usually 2) each arise adjacent to the base of the ovary and are between the stamens adjacent to the lemma of the grass floret. Note that the anterior lodicule (the third lodicule), adjacent to the palea, is suppressed in most grass species. This suppression results in the trimerous arrangement of the lodicules together with the stamens and carpels being overlooked. The lodicules are thought to be involved in opening of the grass flower in readiness for pollination (they become turgid at anthesis, thus opening (pushing apart) the lemma and palea and facilitating wind pollination).&quot; [MaizeGDB:lv (ID # 165572), :Ambrose et al. , (2000). Molecular and Genetic Analysis of the Silky1 Gene Reveal Conservation in Floral Organ Specification between Eudicots and Monocots , Molecular Cell 5 569-579, :Gibbs Russel et al. , (1990). Grasses of southern Africa]") :- x_cid(a65b125bd40e99).
xc_microtheory(a65b125bd40e99,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40e99,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd40e99,238).
xc_kb_names(a65b125bd40e99,[]).
xc_mapping_rows(a65b125bd40e99,[]).
'x_mo-definition'('x_ZEA--0015086',"&quot;The spikelet is the basic unit of the grass inflorescence and each spikelet is usually subtended by a pair of leaf-like (bract-like) structures, called glumes, at its base. The two glumes are referred to as the lower glume and the upper glume.  In Zea each spikelet of the tassel (staminate inflorescence) comprises two florets (flowers). Similarly each spikelet of the lateral branch (ear or pistillate inflorescence) contains initially two florets although one of these is usually arrested in its development very early on. Note that in both the staminate and pistillate inflorescences the spikelets occur in pairs (sessile &amp; pedicellate spikelets), joined to a common pedicel.&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40e9a).
