'x_mo-definition'('x_ZEA--0015171',"&quot;The term tiller is a collective term used for all of the various forms of adventitious shoot which is produced by Zea mays. Tillers are produced by adventitous shoot meristematic tissue (ZEA:xxx). Observations indicate that while axillary buds may be involved in adventitious shoot growth (formation of tillers), several of these shoots (tillers) can arise from a single node.&quot; [MaizeGDB:lv (ID# 165572)]") :- x_cid(a65b125bd40ea3).
