'x_mo-definition'('x_ZEA--0015060',"&quot;The adult leaves are above the juvenile (oldest) leaves. Adult leaves are distinct from juvenile leaves in maize. The juvenile vs adult status is characterized by particular anatomical traits: wax and hair distribution, presence or absence of epidermal cell types, cell wall shape and biochemistry. The change from juvenile-phase to adult-phase leaves  is gradual.&quot; [MaizeGDB:lv, Sylvester et al.:American Journal of Botan 88(12) 2157-2167 , 2001, Freeling &amp; Lane:The Maize Leaf. In The Maize Handbook. ISBN 0387978267]") :- x_cid(a65b125bd40ea5).
