'x_mo-definition'('x_ZEA--0015118',"&quot;The development of the gynoecial tissue from the floral meristem occurs during the ongoing development of the three stamen primordia.The gynoecial tissue develops via the initiation of an adaxial ridge on the remainder of the floral meristem distal to the three stamens. Soon after initiation the gynoecial tissue begins to abort and subsequently degenerates. This abortion and degeneration of this tissue in the lower floret of the pedicellate spikelet occurs before the same process occurs in the upper floret. &quot; [MaizeGDB:lv (ID # 165572), MaizeGDB:60893]") :- x_cid(a65b125bd40ec9).
