'x_mo-definition'('x_ZEA--0015164',"&quot;The meristem which gives rise to the crown roots (ZEA:15066).There are two spatial components of the adventitious root system. 1. A subterranean (below-ground) origin; 2. An aerial (above-ground) origin. The subterranean adventitious roots are frequently called crown roots because they originate from the basal portion of the growing stem known as the crown. The first crown roots (4-5), arranged in a whorl, appear at the base of the second internode about as soon as the tip of the coleoptile reaches the soil surface. A few of the subsequent higher internodes may have a similar number of crown roots (in whorls), after which the successive internodes have more and larger crown roots up to 2-3 internodes above the soil surface.&quot; [MaizeGDB:lv (ID# 165572)]") :- x_cid(a65b125bd40ece).
xc_microtheory(a65b125bd40ece,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40ece,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd40ece,347).
xc_kb_names(a65b125bd40ece,[]).
xc_mapping_rows(a65b125bd40ece,[]).
'x_mo-definition'('x_ZEA--0015095',"&quot;The upper (inner) of the two bract-like structures that subtend the base of the pedicelled spikelets of the ear (pistillate inflorescence). Note that each of the many paired spikelets of the ear (pistillate inflorescence) has an upper glume. Each spikelet is subtended by a pair of glumes (lower &amp; upper glumes). (Vincent, ID#165572)&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40ecf).
