'x_mo-definition'('x_ZEA--0015027',"&quot;Expanded lateral outgrowth of the stem produced in succession from the growing point, and having a bud in its axil. The maize foliar leaf consists of 2 distict parts, the blade (lamina) (a flat portion extending away from the stem (culm), which is the distal part of the whole leaf, and the sheath (a basal part wrapped tightly around the stem), which is the proximal part of the whole leaf. At the junction of blade (lamina) and sheath is an indentation and a hinge of translucent tissue. Each leaf has a pair of auricles.  The auricles are triangular portions of  leaf tissue that are adjacent to the indentation (junction of leaf sheath with leaf blade). Each leaf has a ligule. The ligule is a thin collar of filmy tissue which grows semi perpendicularly from the junction of the leaf sheath and leaf blade on the adaxial (upper) surface of the leaf.&quot; [S. Poethig:1982. In W.F. Sheridan (ed.) , Maize for biological research , p.9-18. Plant Mol. Biol. Assn. , Charlottesville , VA.]") :- x_cid(a65b125bd40ed5).
xc_microtheory(a65b125bd40ed5,'x_zea_mays_anatomy-merged-SUMOMt').
