'x_mo-definition'('x_ZEA--0015062',"&quot;The seminal root system consists of the adventitious lateral roots which are present in the ungerminated caryopsis (kernel, seed) - they are formed during embryogenesis. The adventitious seminal lateral roots arise from 3 to 7 seminal root primordia. These primordia originate 30-40 days postanthesis, and emerge between the scutellum and the first internode. The adventitious seminal lateral root system, the primary root and its associated adventitious lateral roots, forms a small part of the total root system of the plant. These roots are of greatest importance during the early growth of the seedling before the adventitious crown roots of higher internodes become well established.&quot; [MaizeGDB:lv, Feldman in Freeling &amp; Walbot (eds) , 1994. The Maize Handbook , ID # 60920:< new dbxref>, Kiesselbach , ID # 59445:< new dbxref>, Poethig in Sheridan , WF (ed) , 1982. Maize for Biological Research , ID # 25744:< new dbxref>]") :- x_cid(a65b125bd40f0a).
