'x_mo-definition'('x_ZEA--0015077',"&quot;The lowermost leaf on the short lateral (axillary) branch (shank) bearing the ear. The prophyll arises from the lateral (axillary) branch from the most proximal node and is positioned adjacent to the internode of the main culm. The prophyll is distinct from the husk leaves (non-homologous) in having two apices and two distinct midribs (keels; bikeeled).&quot; [MaizeGDB:lv (ID # 165572), MaizeGDB:Clayton &amp; Renvoiz ref ID #]") :- x_cid(a65b125bd40f0b).
