'x_mo-definition'('x_ZEA--0015068',"&quot;Prop ('brace') roots are crown roots which have an aerial (above-ground) origin. They emerge from the extreme basal portion of 2-3 internodes above the soil surface. Their emergence frequently disrupts the leaf sheath tissue that arises from the node immediately below the whorl of prop crown roots. Until each prop root reaches the soil, it remains unbranched and relatively rigid, and is usually covered by a mucilaginous substance that protects the aerial part of the root from drying (dessication). Note that once the prop / brace roots enter the soil they produce numerous lateral adventitious roots (see 'root branches'). The crown roots arising from internodes 2 to approximately 5 tend to grow horizontally for some distance before turning downward. The crown roots from the base of the higher internodes (appearing later in the growing season) grow downward immediately after initiation.&quot; [MaizeGDB:lv, Feldman in Freeling &amp; Walbot (eds) , 1994. The Maize Handbook , ID # 60920:< new dbxref>, Kiesselbach , ID # 59445:< new dbxref>, Poethig in Sheridan , WF (ed) , 1982. Maize for Biological Research , ID # 25744:< new dbxref>]") :- x_cid(a65b125bd40f16).
