'x_mo-definition'('x_ZEA--0015079',"&quot;The culm internode is the region of the culm which is bounded by a culm node at each end. Culm internodes are an integral part of the structure of the culm. Typically the culm internodes are considered homologous with lateral branch internodes of the lateral branches (ear shoots). However, these two types of internodes are biologically distinct (non-homologous). Notwithstanding this non-homology, the general anatomical structure of a typical internode consists of the following: a pithy interior comprised mainly of parenchyma with vascular bundles distributed throughout (as is typical of monocot stem vascular anatomy). In cross section (transverse section) the epidermis is the outer single layer of cells. The walls of the epidermal cells are considerably thickened, lignified and silicified. Stomata are present in the epidermis but are less abundant than in the epidermis of leaves. Immediately below the epidermis is a layer of sclerenchyma which varies from 1-10 cells in thickness. This sclerenchyma tissue does not form a continuous band underneath the epidermis but forms longitudinal bands or strips around the peripheral vascular bundles, alternating with strips of parenchyma beneath the rows of stomata. Within this discontinuous band of sclerenchyma are several rows of vascular bundles, each surrounded by a large amount of sclerenchyma. The peripheral bundles are smaller and are spaced much closer than those in the central part of the internode (in cross section) and are separated from each other and from the peripheral sclerenchyma by narrow tracts of parenchyma. The non-peripheral vascular bundles are surrounded by a bundle sheath, the cells of which are lignified and sclerenchymatous. The sclerenchymatous bundle sheath is much more developed opposite the phloem and xylem of each vascular bundle, forming phloem and xylem caps.&quot; [MaizeGDB:59445, MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40f1d).
xc_microtheory(a65b125bd40f1d,'x_zea_mays_anatomy-merged-SUMOMt').
