'x_mo-definition'('x_ZEA--0015092',"&quot;The penultimate bract-like structure that subtends the lower (sessile) floret of the pedicellate spikelet of the ear (pistillate inflorescence). As part of the lower floret, the outer lemma is oriented in a position that is opposite the palea &amp; adjacent to the lower (outer) glume of the pedicellate spikelet. The lemma arises from the floret pedicel immediately below the palea.&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40f3f).
