'x_mo-definition'('x_ZEA--0015132',"&quot;The rachilla, or central axis, is the structure which bears the distichous glumes at the base and florets above. While the rachilla is recognizable in the spikelets of the 'tassel' in Zea mays, the rachilla of the 'ear' spikelets is much reduced. The bases of the rachillas of the ear can be considered to have anastomosed, forming the collective structure that is referred to as the cob.&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40f41).
