'x_mo-definition'('x_ZEA--0015101',"&quot;The gynoecium development of the upper floret begins with the production of a ridge on the abaxial surface of the apical meristem of the floret, distal to the third stamen (which later degenerates). This is the stylar ridge. Continued overgrowth of the shoot apex (which becomes the ovule primordium) by the ring of stylar tissue leads to the formation of the stylar canal, which is detected as a slight protruberance on the mature ovary. (Cheng &amp; Pareddy, ID#60893, &quot; [MaizeGDB:lv (ID # 165572), MaizeGDB:60893]") :- x_cid(a65b125bd40f61).
xc_microtheory(a65b125bd40f61,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40f61,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd40f61,659).
