'x_mo-definition'('x_ZEA--0015144',"&quot;Two, small, scale-like. pale-green structures (glandular-like organs) found adjacent to the inner surface of the base of the lemma of the floret. The adjacent margins of the two lodicules (opposite the mid-line of the lemma) are adpressed to each other while the inner surfaces of the lodicules form an angle of approximately 80 degrees to each other. Within the triangle of basal tissue, bounded on two sides by the two lodicules, are located the three filaments of the stamens. Just prior to anthesis the lodicules grow/swell laterally and the triangle of space between the lodicules is almost obscured. The two lodicules are thought to be involved in opening of the grass floret (flower) in readiness for pollination (at anthesis they grow/become increasingly turgid and are presumed to contribute to the displacing of the adjacent lemma and glume which facilitates the exsertion of the anthers for wind pollination). Gibbs Russell et al., Grasses of southern Africa, 1990; Ambrose et al., (2000), Molecular and Genetic Analyses of the Silky1 Gene Reveal Conservation in Floral Organ Specification between Eudicots and Monocots, Molecular Cell 5:569-579. Leszek Vincent 06/2000.&quot; [MaizeGDB:lv (ID# 165572)]") :- x_cid(a65b125bd40f63).
xc_microtheory(a65b125bd40f63,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40f63,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd40f63,663).
xc_kb_names(a65b125bd40f63,[]).
xc_mapping_rows(a65b125bd40f63,[]).
'x_mo-definition'('x_ZEA--0015082',"&quot;The mesocotyl is the first culm internode of the maize culm. The mesocotyl is the culm internode below the plumule, between the coleoptile node and the scutellar node. This first culm internode is a very characteristic and unique feature of the Poaceae (alt. Gramineae). The first culm internode is frequently termed the 'mesocotyl' in the literature. This first culm internode is not evident 15 days after pollination, when the coleoptile node is virtually in contact with the scutellar node. Subsequent intercalary growth results in considerable lengthening of the first culm internode (mesocotyl) in the embryo. &quot;The internode between the scutellar node and coeoptile in the embryo and seedling of Poaceae&quot; (K. Esau. 1977. The Anatomy of Seed Plants, John Wiley &amp; Sons)&quot; [MaizeGDB:208059, MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40f64).
xc_microtheory(a65b125bd40f64,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40f64,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd40f64,665).
