'x_mo-definition'('x_ZEA--0015139',"&quot;Gynoecium is the collective term for all of the carpels or pistils of a flower (floret). Each carpel or pistil comprises of a stigma, style and ovary. In Zea the silk comprises the stigma and extended style. &quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40f6b).
