'x_mo-definition'('x_ZEA--0015084',"&quot;The 'ear' is the distal part of a lateral (axillary) branch and bears the functionally-female florets in a highly contracted inflorescence. The upper one or two culm axillary buds (associated with the nodes of the culm (stalk)), located about midway on the culm, develop fully into short lateral branches, each terminating in a developing ear capable of producing mature kernels (caryopses). Each of the culm axillary buds is covered with about 8-14 modified leaves called husks, and a prophyll (the most basal modified leaf on the lateral branch). The ear branch (lateral branch, shank) consists of nodes and short internodes. The ear itself does not have lateral branches but its thick axis (called the cob), is similar to the central spike of the tassel in that it produces multiple longitudinal rows of paired spikelets (polystichous phyllotaxy). Each spikelet is ensheathed (enclosed) by a pair of glumes and contains only one functionally-female floret. Although two florets are initiated during spikelet ontogeny, only the upper floret develops; the lower floret aborts at an early stage of development. Both florets within a spikelet produce a lemma, but usually only the upper floret produces a palea. The palea of the lower floret either does not initiate or remains rudimentary. Each functionally-female floret produces an ovary with an elongated silk (style) covered with hairs (trichomes). Note that the culm axillary buds, which are not appropriately placed for full development, degenerate at an early stage. The amount of growth before degeneration/senescence occurs varies, as the buds may either die without much development or form ears several centimeters long, which resemble the functional ears until they senesce (die). From a perspective of developmental biology the ear is initially smooth. But numerous outgrowths (primordia) typically soon appear (in an acropetal direction) which become two lobed (spikelet pair primordium), each lobe finally giving rise to a spikelet (the basic definitive structure of the grass inflorescence) with two florets (flowers). The two glumes, which arise from the pedicel of each spikelet, subtend and ensheath each spikelet and are formed in the same manner as the vegetative leaves. The glume initials emanate from the tissue of the spikelet primordium during the ontogeny of the spikelet. Note that Zea mays is monoecious (separate male &amp; female flowers/florets are found on the same plant). The growth of the ear (pistillate inflorescence) is indeterminate. (Kiesselbach, ID#59445, Cheng &amp; Pareddy, ID#60893, Vincent, ID#165572)&quot; [MaizeGDB:lv (ID # 165572), MaizeGDB:59445, MaizeGDB:60893]") :- x_cid(a65b125bd40f6c).
xc_microtheory(a65b125bd40f6c,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40f6c,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd40f6c,682).
