'x_mo-definition'('x_ZEA--0015102',"&quot;The gynoecium development of the lower floret begins with the production of a ridge on the abaxial surface of the apical meristem of the floret, distal to the third stamen (which later degenerates). This is the stylar ridge. While the development of this stylar ridge is very similar to that of the upper florets, the development does not proceed beyond the early ridge stage.&quot; [MaizeGDB:lv (ID # 165572), MaizeGDB:60893]") :- x_cid(a65b125bd40f79).
