'x_mo-definition'('x_ZEA--0015085',"&quot;The functionally-male flowering structure (staminate inflorescence) which terminates the culm (stem) of a Zea mays plant. The tassel is a branched inflorescence and consists of a central spike (rachis) and about 10-50 lateral branches. Many paired spikelets (pedicellate &amp; sessile) arise from the central spike and lateral branches. The paired spikelets on the central spike occur in many ranks (longitudinal rows) around the central spike. The paired spikelets of the lateral branches are arranged in only two rows on the lower (adaxial) surface of each lateral branch. Each spikelet bears two male (staminate) florets, the upper and the lower floret. The development of the upper floret is about 2-3 days ahead of the lower floret (measured at anthesis). Each spikelet has a pair of leaf-like (bract-like) glumes, arising from the spikelet pedicel, which ensheath (encase) the two florets within. Within the glumes each floret is further enclosed by a pair of thin scale-like bracts - the lemma (located adjacent to the glume) and a palea (located opposite to the lemma and adjacent to the palea of the other floret in the spikelet). Within each floret, two of the three stamens are located adjacent to the margins of the palea; the third stamen is located adjacent to the midline of the lemma and is flanked by two lodicules. The two lodicules swell at the commencement of anthesis (period from floret opening to fertilization). This swelling forces apart the lemma and palea enclosing the floret, which facilitates the extrusion of the anthers via the elongation of the filaments. Following extrusion, the anthers dangle downward and shed pollen from an opening at the apex (tip) of each anther locule. The tassel exhibits an indeterminate growth pattern. Note that Zea mays is monoecious (separate male &amp; female flowers/florets borne on the same plant). From a perspective of developmental biology the central axis and lateral branches of the tassel are at first smooth. But numerous outgrowths (primordia) typically soon appear (in an acropetal direction) which become two lobed (spikelet pair primordium), each lobe finally giving rise to a spikelet (the basic definitive structure of the grass inflorescence) with two florets (flowers). The two glumes, which arise from the pedicel of each spikelet, subtend and ensheath each spikelet and are formed in the same manner as the vegetative leaves. The glume initials emanate from the tissue of the spikelet primordium during the ontogeny of the spikelet.&quot; [MaizeGDB:59445, MaizeGDB:60893, MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40f7d).
