'x_mo-definition'('x_ZEA--0015166',"&quot;The meristem which gives rise to the subterranean crown roots (ZEA:15067).The subterranean crown roots are a component of the adventitious root system. They are termed crown roots because they originate from the basal portion of the growing stem known as the crown. The first subterranean crown roots (4-5), arranged in a whorl, appear at the base of the second internode about as soon as the tip of the coleoptile reaches the soil surface. A few of the subsequent higher internodes may have a similar number of crown roots (in whorls), after which the successive internodes have more and larger crown roots up to 2-3 internodes above the soil surface.&quot; [MaizeGDB:lv (ID# 165572)]") :- x_cid(a65b125bd40f82).
