'x_mo-definition'('x_ZEA--0015064',"&quot;Some of the lateral roots of the maize plant comprise the seminal root system. These lateral roots are present in the ungerminated caryopsis (kernel, seed) - they are formed during embryogenesis. The seminal lateral roots arise from 3 to 7 seminal root primordia. These primordia originate 30-40 days post-anthesis, and emerge between the scutellum and the first internode. While these lateral roots comprise the seminal root system they are also part of the adventitious root system.&quot; [MaizeGDB:lv, Feldman in Freeling &amp; Walbot (eds) , 1994. The Maize Handbook , ID # 60920:< new dbxref>, Kiesselbach , ID # 59445:< new dbxref>, Poethig in Sheridan , WF (ed) , 1982. Maize for Biological Research , ID # 25744:< new dbxref>]") :- x_cid(a65b125bd40f96).
