'x_mo-definition'('x_ZEA--0015146',"&quot;The development of the gynoecial tissue from the floral meristem occurs during the ongoing development of the three stamen primordia.The gynoecial tissue develops via the initiation of an adaxial ridge on the remainder of the floral meristem distal to the three stamens. Soon after initiation the gynoecial tissue begins to abort and subsequently degenerates. This abortion and degeneration of this tissue in the upper floret of the sessile spikelet occurs after the same process occurs in the lower floret. &quot; [MaizeGDB:lv (ID# 165572), MaizeGDB:60893]") :- x_cid(a65b125bd40fad).
xc_microtheory(a65b125bd40fad,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40fad,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
