'x_mo-definition'('x_ZEA--0015140',"&quot;The husk structure consists mostly of the husk sheath. The husk sheath is the proximal (basal) portion of the husk that initiates at each of the nodes of the lateral branch (shank). The husk sheathes are much broader and thinner than the sheathes of adult and juvenile leaves. The broadness of the husk sheathes enable them to cover much of the circumference of the developing ear. The distal end of the husk sheath ends with the husk ligule region which is terminated with a diminutive (short) or extended husk leaf (flag leaf). The outer husks (lowermost/most proximal) on the lateral branch (shank) are distichous (in two vertical ranks or rows on opposite sides of an axis) like the adult &amp; juvenile leaves. While the inner (upper) husks are polystichous (arranged in several rows).\n\nNote that the term husk (instead of husk sheath) is colloquially used for the modified leaf tissue which surrounds the ear and the term is seldom associated with husk ligule and husk leaf (flag leaf). However, botanically, the term husk should be used for the entire structure (fide Kiesselbach, 1949), comprising the husk sheath, husk ligule and husk leaf (the latter components frequently being very diminutive). The perspective that husks are somewhat homologous with the adult and juvenile leaves justifies the usage of the term husk sheath for the predominant portion of the husk which surrounds the ear.&quot; [MaizeGDB:lv (ID# 165572), MaizeGDB:kiesselbach (ID# 59445)]") :- x_cid(a65b125bd40fb0).
xc_microtheory(a65b125bd40fb0,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40fb0,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd40fb0,829).
xc_kb_names(a65b125bd40fb0,[]).
xc_mapping_rows(a65b125bd40fb0,[]).
