'x_mo-definition'('x_ZEA--0015128',"&quot;Each spikelet in either of the inflorescences in Zea is subtended by a pair of leaf-like (bract-like) structures, called glumes, at its base. The two glumes are referred to as the lower glume and the upper glume. The spikelet is the basic unit of the grass inflorescence. In Zea each spikelet of the tassel (staminate inflorescence) comprises two florets (flowers). Similarly each spikelet of the lateral branch (ear or pistillate inflorescence) contains initially two florets although one of these is usually arrested in its development very early on. Note that in both the staminate and pistillate inflorescences the spikelets occur in pairs (sessile &amp; pedicellate spikelets), joined to a common pedicel.&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40fb5).
xc_microtheory(a65b125bd40fb5,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40fb5,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
