'x_mo-definition'('x_ZEA--0015075',"&quot;The central axis/core of the 'ear' (distal end of the lateral branch/ear shoot) upon which the kernels (caryopses) are borne. The cob is similar to the central spike of the tassel (male inflorescence) in that it produces multiple rows of paired spikelets (polystichous phyllotaxy). &quot; [MaizeGDB:60893, MaizeGDB:165572]") :- x_cid(a65b125bd40fbe).
