'x_mo-definition'('x_ZEA--0015096',"&quot;The lower (outer) of the two bract-like structures that subtend the base of the pedicelled spikelets of the ear (pistillate inflorescence). Note that each of the many paired spikelets of the ear (pistillate inflorescence) has a lower glume. Each spikelet is subtended by a pair of glumes (lower &amp; upper glumes). (Vincent, ID#165572)&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40fcc).
xc_microtheory(a65b125bd40fcc,'x_zea_mays_anatomy-merged-SUMOMt').
