'x_mo-definition'('x_ZEA--0015074',"&quot;The shank is the portion of the lateral branch below the ear. 8-14 modified leaves, called husks, are arranged up the shank in an alternate pattern and surround the developing ear. The basal husk leaf is termed the prophyll and is not homologous with the other husk leaves. Each husk leaf arises from a node along the length of the lateral branch. A dormant lateral (axillary) bud is found in the axil of each husk leaf.&quot; [MaizeGDB:232442, MaizeGDB:165572]") :- x_cid(a65b125bd40fcd).
