'x_mo-definition'('x_ZEA--0015133',"&quot;The hair-like styles in maize. Each silk arises from the distal end (silk scar region) of each of the two anterior functional carpels. A vascular strand passes up through each anterior carpel into the attached silk and extends to the branched tip of the silk where it divides and extends down the length of each branch. The surface of the silk becomes covered with numerous hairs (trichomes) which arise from the epidermal cells. The hairs are most numerous along the edges of the silk. Each hair (trichome) is composed of four rows of cells, so arranged that the intercelllular spaces between the rows form a continuous opening through the center of the hair. At the base of the silk is a growth zone (intercalary growth) where new cells develop causing continuous elongation of the silk until it is pollinated and fertilization occurs. At this time the zone of elongation shrivels up, forming the place where the silk later breaks loose. The silk is perhaps best considered as consisting of a very short style without hairs, above which is the region of intercalary growth. The branched part of the silk corresponds to the stigma of other grasses. The region formed by the intercalary growth zone is an addition to the stigma and has nothing homologous to it in most grasses.&quot; [MaizeGDB:kiesselbach (ID # 59445), MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40fd2).
xc_microtheory(a65b125bd40fd2,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40fd2,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
