'x_mo-definition'('x_ZEA--0015088',"&quot;The palea is the uppermost bract-like structure that subtends the grass floret. The palea is oriented in a position that is opposite the lemma which also subtends the floret and arises from the floret pedicel immediately below the palea. See elsewhere for further information on the palea associated with each individual floret of the male and female spikelets. The palea is a bikeeled structure and its relationship to the leaf (homology) is unknown.&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd40fe0).
