'x_mo-definition'('x_ZEA--0015063',"&quot;The adventitious root system consists of all those roots that arise in the basal intercalary meristem of the lower internodes (above the first internode) of the culm (stem). The adventitious root system comprises the bulk of the lateral roots of the maize plant. There are two spatial components of the adventitious root system. 1. A subterranean (below-ground) origin; 2. An aerial (above-ground) origin. The subterranean adventitious roots are frequently called crown roots because they originate from the basal portion of the growing stem known as the crown. The first crown roots (4-5), arranged in a whorl, appear at the base of the second internode about as soon as the tip of the coleoptile reaches the soil surface. A few of the subsequent higher internodes may have a similar number of crown roots (in whorls), after which the successive internodes have more and larger crown roots up to 2-3 internodes above the soil surface. Note that the crown roots of the adventitious root system may appear to arise from the nodes of the culm but careful inspection will reveal their origin from the very base of the internode, frequently disrupting the leaf sheath tissue that arises from the node immediately below the whorl of crown roots. Those crown roots which are initially aerial in position relative to the soil surface are termed 'brace' or 'prop' roots. Until each prop root reaches the soil, it remains unbranched and relatively rigid, and is usually covered by a mucilaginous substance that protects the aerial part of the root from drying (dessication). Note that once the brace / prop roots enter the soil they produce numerous lateral adventitious roots (see 'root branches'). The subterranean crown roots produce numerous lateral adventitious roots early in their development. The crown roots arising from internodes 2 to approximately 5 tend to grow horizontally for some distance before turning downward. The crown roots from the base of the higher internodes (appearing later in the growing season) grow downward immediately after initiation.&quot; [MaizeGDB:lv, Feldman in Freeling &amp; Walbot (eds) , 1994. The Maize Handbook , ID # 60920:< new dbxref>, Kiesselbach , ID # 59445:< new dbxref>, Poethig in Sheridan , WF (ed) , 1982. Maize for Biological Research , ID # 25744:< new dbxref>]") :- x_cid(a65b125bd40fe9).
xc_microtheory(a65b125bd40fe9,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd40fe9,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd40fe9,949).
xc_kb_names(a65b125bd40fe9,[]).
xc_mapping_rows(a65b125bd40fe9,[]).
'x_mo-definition'('x_ZEA--0015067',"&quot;The subterranean crown roots are a component of the adventitious root system. They are termed crown roots because they originate from the basal portion of the growing stem known as the crown. The first subterranean crown roots (4-5), arranged in a whorl, appear at the base of the second internode about as soon as the tip of the coleoptile reaches the soil surface. A few of the subsequent higher internodes may have a similar number of crown roots (in whorls), after which the successive internodes have more and larger crown roots up to 2-3 internodes above the soil surface. Note that the crown roots above the soil surface (aerial) are frequently called 'brace' or 'prop' roots. The crown roots emerge from the extreme base of the internode. The subterranean crown roots produce numerous lateral adventitious roots (see 'root branches')  early in their development. The crown roots arising from internodes 2 to approximately 5 tend to grow horizontally for some distance before turning downward. The crown roots from the base of the higher internodes (appearing later in the growing season) grow downward immediately after initiation.&quot; [MaizeGDB:lv, Feldman in Freeling &amp; Walbot (eds) , 1994. The Maize Handbook , ID # 60920:< new dbxref>, Kiesselbach , ID # 59445:< new dbxref>, Poethig in Sheridan , WF (ed) , 1982. Maize for Biological Research , ID # 25744:< new dbxref>]") :- x_cid(a65b125bd40fea).
