'x_mo-definition'('x_ZEA--0015059',"&quot;Juvenile leaves are distinct from adult leaves in maize. The juvenile vs adult status is characterized by particular anatomical traits: wax and hair distribution, presence or absence of epidermal cell types, cell wall shape and biochemistry. The juvenile leaves include the oldest leaves. The first 5 juvenile leaves are representative of the 5 embryonic leaves found in the maize kernel (caryopsis). The distinctness of these 5 embryonic leaves is not yet represented in the ontology. The change from juvenile- phase to adult-phase leaves  is gradual.&quot; [MaizeGDB:lv, Sylvester et al.:American Journal of Botany 88(12) 2157-2167 , 2001, Freeling &amp; Lane:The Maize Leaf. In The Maize Handbook , ISBN 0387978267]") :- x_cid(a65b125bd41014).
