'x_mo-definition'('x_ZEA--0015170',"&quot;A dry, one-seeded, indehiscent fruit with the seed coat fused to the pericarp. The caryopsis includes the ovary. The caryopsis is the typical fruit structure of the grass (Poaceae / Gramineae) family.&quot; [MaizeGDB:lv (ID# 165572), Chapman:The Biology of Grasses - ISBN 0 85199 111 4, Harris &amp; Harris:Plant Identification Terminology - An Illustrated Glossary , ISBN 0 9640221 5 X]") :- x_cid(a65b125bd41016).
