'x_mo-definition'('x_ZEA--0015071',"&quot;a lateral branch axillary (lateral) bud is found in the axil of each of the husk leaves and the prophyll, which arise from the lateral branch nodes of the shank (proximal end of the lateral (axillary) branch(es)). All of the lateral branch axillary buds remain dormant throughout the life-span of the Zea mays plant.&quot; [MaizeGDB:59445, MaizeGDB:60893, MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd41017).
