'x_mo-definition'('x_ZEA--0015076',"&quot;The culm nodes are regions of dense tissue appearing as slightly swollen regions along the length of the culm. The culms of typical eastern Nebraska corn plants consist of about 24 culm nodes (alternating with culm internodes). The number of culm nodes may vary according to regional type and environmental effects. Approximately 8 culm internodes remain very short (contracted) and subterranean, forming an inverted cone-shaped basal end of the culm (stem) known as the crown. Culm nodes are an integral part of the structure of the culm (stalk). Culm nodes are not biologically homologous with lateral branch nodes, although they are colloquially referred to as 'nodes'. Notwithstanding this non-homology, the general anatomical structure of a typical node consists of the following: the structure of nodes is more complicated than that of the internodes due to the branching and cross connections between the vascular bundles forming the nodal complex. The vascular bundles with their cross connections fill up most of the space of the node, so there is relatively little parenchyma. In the zone of leaf attachment at the culm nodes, the epidermis of the adjacent culm internodes becomes continuous over the attached leaf sheath. Not much elongation occurs in the culm nodes and no protoxylem lacunae are formed. The arrangement of the tissues in the vascular bundles is more irregular and no bundle caps are formed in the endosperm adjacent to the vascular tissue. As the vascular bundles enter a culm node from below, they enlarge in diameter and form cross connections, creating a tangled network which extends for several millimeters up into the adjacent internode. Many of the vascular bundles branch as they pass through the culm node, while some turn abruptly sideways for a short distance. Some vascular bundles pass from the culm node into the base of the leaf sheath.&quot; [MaizeGDB:59445, MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd4101a).
xc_microtheory(a65b125bd4101a,'x_zea_mays_anatomy-merged-SUMOMt').
