'x_mo-definition'('x_ZEA--0015069',"&quot;A root branch is an adventitious root that emerges from any of the various types of lateral root. Root branches arise at varying points behind (posterior to) the zone of root hair formation on the primary root. Root branches emerge from the surface of the main roots (the various types of lateral roots) at irregular intervals. When a root branches, the initial of each branch is formed from cells of the pericycle. Via cell division a bulging hemispherical mass of meristematic tissue is formed. The outer part of this forms the beginning of the rootcap, while the cells of the growing point are near the flat basal part of the hemispherical mass. During elongation the new root branch is forced through the adjoining tissues of the cortex of the originating root and emerges at the surface. As the xylem and phloem tissues are differentiated in the root branch they become joined to those of the originating root.&quot; [MaizeGDB:lv, Kiesselbach , ID # 59445:< new dbxref>]") :- x_cid(a65b125bd41026).
