'x_mo-definition'('x_ZEA--0015148',"&quot;The last leaf to emerge in a determinate plant in the Poaceae (determinate growth: formation of a restricted number of lateral organs by an apical meristem; apical meristem terminates growth e.g. tassel &amp; lateral branch meristems). Referred to as the &quot;flag leaf&quot; in cereal (grain) crops. The term 'flag leaf' should not be confused with 'flag leaves' which is a synonym term frequently used for the husk leaf (extended lamina) of the husks of sweet corn varieties.\n\nThe flag leaf is frequently much less robust than the other adult leaves. In some cases the midrib is much reduced rendering the leaf very mobile.&quot; [MaizeGDB:lv (ID # 165572), MaizeGDB:esau (ID# 139825)]") :- x_cid(a65b125bd41029).
