'x_mo-definition'('x_ZEA--0015172',"&quot;A leaf primordium is typically referred to as a cell/an organized series of cells in their earliest stage of differentiation with the ontogenetic goal of forming a leaf. A leaf primordium is initiated by cell divisions in the peripheral region of the shoot apex, more or less far below the distal zone of the apical meristem. The first divisions occur in one or more layers beneath the protoderm and are periclinal to the surface of the shoot apex. In Zea the leaf primordium originates from about 250 cells in at least two layers forming a ring of founder cells within the apical meristem tissue associated with the leaf. Each founder cell divides about the same number of times to form the 6 mm square-shaped leaf primordium. The primordial stages of development ends when the lateral veins are complete and the periclinal divisions of the ligule are in progress. Three stages of leaf development are noted: founder cell (meristem founder cell), primordial and postprimordial. The location of each primordium, in relation to the sites of the previously formed leaves, is determined by the phyllotaxy.&quot; [MaizeGDB:lv (ID# 165572), MaizeGDB:Esau (ID# 139825), MaizeGDB:Freeling &amp; Lane (ID# 60922)]") :- x_cid(a65b125bd4102c).
xc_microtheory(a65b125bd4102c,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd4102c,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
