'x_mo-definition'('x_ZEA--0015100',"&quot;The uppermost bract-like structure that subtends the lower (sessile) floret of the pedicellate spikelet of the ear (pistillate inflorescence). This palea either does not initiate or remains rudimentary. The palea is oriented in a position that is opposite the lemma which subtends the same floret. The palea arises from the floret pedicel immediately above the lemma. (Vincent, ID#165572)&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd4102d).
