'x_mo-definition'('x_ZEA--0015070',"&quot;The lateral branch internode is the region of the lateral branch which is bounded by a lateral branch node at each end. Lateral branch internodes are an integral part of the structure of the lateral branches (ear shoots). Lateral branch internodes are not biologically homologous with culm internodes, although they are colloquially referred to as 'internodes'. Notwithstanding this non-homology, the general anatomical structure of a typical internode consists of the following: a pithy interior comprised mainly of parenchyma with vascular bundles distributed throughout (as is typical of monocot stem vascular anatomy). In cross section (transverse section) the epidermis is the outer single layer of cells. The walls of the epidermal cells are considerably thickened, lignified and silicified. Immediately below the epidermis is a layer of sclerenchyma which varies from 1-10 cells in thickness. This sclerenchyma tissue does not form a continuous band underneath the epidermis but forms longitudinal bands or strips around the peripheral vascular bundles, alternating with strips of parenchyma beneath the rows of stomata. Within this discontinuous band of sclerenchyma are several rows of vascular bundles, each surrounded by a large amount of sclerenchyma. The peripheral bundles are smaller and are spaced much closer than those in the central part of the internode (in cross section) and are separated from each other and from the peripheral sclerenchyma by narrow tracts of parenchyma. The non-peripheral vascular bundles are surrounded by a bundle sheath, the cells of which are lignified and sclerenchymatous. The sclerenchymatous bundle sheath is much more developed opposite the phloem and xylem of each vascular bundle, forming phloem and xylem caps.&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd41042).
xc_microtheory(a65b125bd41042,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd41042,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
