'x_mo-definition'('x_ZEA--0015141',"&quot;The husk leaf (lamina) is a small (short, reduced - less than 20 mm) portion of modified leaf-blade tissue that is present at the distal end of each husk. The husk leaf region commences with a modified and diminutive ligular region and extends into a tapered lamina which is photosynthetic. The husk leaf is considered to be somewhat homologous with the leaf blade (lamina) of the adult and juvenile leaves. In all occurrences the husk leaf (lamina) lacks the well developed central midrib (midvein) and the widespread lateral veins are much less robust.The husk leaf is reduced in most forms of dent corn. However, in sweet corns the husk leaves are considerably longer (60 mm or longer) and are  frequently referred to as flag leaves. These 'flag leaves' should not be confused with the &quot;flag leaf&quot; (ZEA:15148). Where the husk leaves are well developed (flag leaves) the husk leaves are noticeably lacking in rigidity.&quot; [MaizeGDB:lv (ID# 165572), MaizeGDB:kiesselbach (ID# 59445), MaizeGDB:ID# 106158]") :- x_cid(a65b125bd41056).
xc_microtheory(a65b125bd41056,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd41056,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
xc_source_line(a65b125bd41056,1177).
xc_kb_names(a65b125bd41056,[]).
xc_mapping_rows(a65b125bd41056,[]).
'x_mo-definition'('x_ZEA--0015142',"&quot;The husk ligule in Zea mays is sometimes absent. When present it takes the form of a diminutive protruding line of tissue on the inner/upper (adaxial) surface of the husk leaf at the boundary between the husk sheath and the tapered husk leaf (lamina). As in the ligules of adult and juvenile leaves, this unique line of epidermal tissue appears to be composed of 'fused hairs'. The husk leaf ligule is relatively short (laterally), spanning the width of the tapered end of the distal end of the husk.&quot; [MaizeGDB:lv (ID# 165572)]") :- x_cid(a65b125bd41057).
xc_microtheory(a65b125bd41057,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd41057,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
