'x_mo-definition'('x_ZEA--0015036',"&quot;The Zea mays Plant Structure Ontology consists of controlled vocabulary terms for Zea mays anatomy (including morphology). Note that the name Plant Structure Ontology is used in preference to Anatomy Ontology as plant scientists differ on the appropriate use of the term 'anatomy'. In the strict sense 'anatomy' includes 'morphology'. However, some plant scientists relate more easily to external features being termed morphology &amp; internal features being termed anatomy. To overcome possible misunderstanding 'Plant Structure' is being used as the preferred term with 'Anatomy (incl. morphology)' as a synonym.&quot; [MaizeGDB:lv (ID # 165572]") :- x_cid(a65b125bd4105a).
