'x_mo-definition'('x_ZEA--0015116',"&quot;The uppermost bract-like structure that subtends the lower (sessile) floret of the sessile spikelet of the tassel (staminate inflorescence). The palea is oriented in a position that is opposite the lemma which subtends the same floret. The palea arises from the floret pedicel immediately above the lemma. &quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd41066).
