'x_mo-definition'('x_ZEA--0015110',"&quot;The lower (outer) of the two leaf-like (bract-like) structures that subtend the base of the pedicelled spikelets of the tassel (staminate inflorescence). Note that each of the many paired spikelets of the tassel (staminate inflorescence) has a lower glume. Each spikelet is subtended by a pair of glumes (lower &amp; upper glumes).&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd4106b).
