'x_mo-definition'('x_ZEA--0015066',"&quot;There are two spatial components of the adventitious root system. 1. A subterranean (below-ground) origin; 2. An aerial (above-ground) origin. The subterranean adventitious roots are frequently called crown roots because they originate from the basal portion of the growing stem known as the crown. The first crown roots (4-5), arranged in a whorl, appear at the base of the second internode about as soon as the tip of the coleoptile reaches the soil surface. A few of the subsequent higher internodes may have a similar number of crown roots (in whorls), after which the successive internodes have more and larger crown roots up to 2-3 internodes above the soil surface. Note that the crown roots of the adventitious root system may appear to arise from the nodes of the culm but careful inspection will reveal their origin from the very base of the internode, frequently disrupting the leaf sheath tissue that arises from the node immediately below the whorl of crown roots. Those crown roots which are initially aerial in position relative to the soil surface are termed 'brace' or 'prop' roots. Until each prop root reaches the soil, it remains unbranched and relatively rigid, and is usually covered by a mucilaginous substance that protects the aerial part of the root from drying (desiccation). Note that once the brace / prop roots enter the soil they produce numerous lateral adventitious roots (see 'root branches'). The subterranean crown roots produce numerous lateral adventitious roots early in their development. The crown roots arising from internodes 2 to approximately 5 tend to grow horizontally for some distance before turning downward. The crown roots from the base of the higher internodes (appearing later in the growing season) grow downward immediately after initiation.&quot; [MaizeGDB:lv]") :- x_cid(a65b125bd41078).
