'x_mo-definition'('x_ZEA--0015080',"&quot;The lateral branch nodes are regions of dense tissue appearing as slightly swollen regions along the length of the lateral branch. Lateral branch nodes are an integral part of the structure of the lateral branchs (ear shoots). Lateral branch internodes are not biologically homologous with culm nodes, although they are colloquially referred to as 'nodes'. Notwithstanding this non-homology, the general anatomical structure of a typical node consists of the following: the structure of nodes is more complicated than that of the internodes due to the branching and cross connections between the vascular bundles forming the nodal complex. The vascular bundles with their cross connections fill up most of the space of the node, so there is relatively little parenchyma. In the zone of husk and prophyll attachment at the lateral branch nodes, the epidermis of the adjacent lateral branch internodes becomes continuous over the prophyll and husk. Not much elongation occurs in the lateral branch nodes and no protoxylem lacunae are formed. The arrangement of the tissues in the vascular bundles is more irregular and no bundle caps are formed in the endosperm adjacent to the vascular tissue. As the vascular bundles enter a lateral branch node from below, they enlarge in diameter and form cross connections, creating a tangled network which extends for several millimeters along the length of the lateral branch. Many of the vascular bundles branch as they pass through the lateral branch node, while some turn abruptly sideways for a short distance. Some vascular bundles pass from the lateral branch node into the base of the prophyll of the sheathing base of the husk leaf.&quot; [MaizeGDB:59445, MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd41086).
xc_microtheory(a65b125bd41086,'x_zea_mays_anatomy-merged-SUMOMt').
