'x_mo-definition'('x_ZEA--0015155',"&quot;The meristem which produces the tassel and the ear inflorescences. The tassel (functionally male inflorescence) meristem is derived from the apical meristem of the growing point of the determinate culm. An ear meristem is derived from the apical meristem of a lateral branch which produces the ear (functionally female inflorescence).&quot; [MaizeGDB:lv (ID# 165572)]") :- x_cid(a65b125bd41097).
