'x_mo-definition'('x_ZEA--0015009',"&quot;The ligule in Zea mays is a protruding line of tissue on the inner/upper (adaxial) surface of the leaf at the boundary between the leaf-sheath and the leaf blade (lamina) - the ligular region of the leaf. This unique line of epidermal tissue appears to be composed of 'fused hairs'. The ligule is oriented almost perpendicular to the adjacent leaf surface.&quot; [M. Freeling &amp; B. Lane:1994. The Maize Leaf. In M. Freeling &amp; V. Walbot (eds.) (1994). The Maize Handbook. Springer-Verlag , New York , ISBN 3-540-97826-7, A. Fahn:(1982). Plant Anatomy , p.244-245 , ISBN 0-08-028029-3, Gibbs Russell et al.:(1990). Grasses of Southern Africa , ISBN 0-620-14846-2, MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd4109a).
