'x_mo-definition'('x_ZEA--0015035',"&quot;Leaf blade auricles are small appendages (portion of leaf tissue) in the collar area of the leaf (proximal end (base) of the lamina (leaf blade)) immediately lateral to the ligule. In Zea mays the auricles appear to arise from the 'collar' tissue of the leaf blade. Each auricle has an equilateral triangular shape. The base of the triangle forming the proximal margin of the leaf, the upper equilateral side being the boundary of the proximal region of the leaf blade. The lower equilateral side being the boundary of the distal edge of the leaf sheath. There are two auricles on each adult leaf of Zea mays. The auricular tissue extends from the adaxial to the abaxial surfaces of the lamina.&quot; [MaizeGDB:60922, ISBN:0620148462, MaizeGDB:165572]") :- x_cid(a65b125bd410a6).
