'x_mo-definition'('x_ZEA--0015087',"&quot;The penultimate bract-like structure that subtends the grass floret. The lemma is oriented in a position that is opposite the palea in each floret. The lemma arises from the floret pedicel immediately below the palea. See elsewhere for further information on the lemma associated with each individual floret of the male and female spikelets. Lemmas are considered to be homologous to the vegetative leaf.&quot; [MaizeGDB:lv (ID # 165572)]") :- x_cid(a65b125bd410a8).
