'x_mo-definition'('x_ZEA--0015078',"&quot;The husks are modified leaves which arise from the short lateral (axillary) branch (shank) bearing the ear. They surround the developing ear. The lower (outer) husks are arranged in a distichous pattern (opposite rows and alternate occurrence, like the foliar leaves) while the upper (inner) husks are polystichous in arrangement. Husks are considered to be somewhat homologous with the adult and juvenile leaves (foliar leaves). Vestiges of the ligular region and lamina (husk leaf, flag leaf) of the husk may be present. Some strains of maize (Zea mays) (e.g. sweet corn) produce husks with a prominent ligule and husk leaf (lamina), which are sometimes called &quot;flag leaves&quot;. Husks are relatively thin and flat, unlike the adult and juvenile foliar leaves. The sheaths of the husks are much broader and thinner than the sheaths of the foliar (ordinary) leaves. The venation lacks the presence of a distinct midvein, while lateral veins predominate throughout the husk. Each husk is attached to a unique lateral branch node on the shank (growing lateral (axillary) branch) of the ear. The lowermost husk on the shank, between the shank and the adjacent internode of the main culm, is a prophyll (ZEA:15077). It is easily confused as being a husk but the prophyll is not homologous with a husk. \n\nNote that the term husk is colloquially used for the modified leaf tissue which surrounds the ear and the term is seldom associated with husk ligule and husk leaf (flag leaf). However, botanically, the term husk should be used for the entire structure (fide Kiesselbach, 1949), comprising the husk sheath, husk ligule and husk leaf (the latter components frequently being very diminutive). The perspective that husks are somewhat homologous with the adult and juvenile leaves justifies the usage of the term husk sheath for the predominant portion of the husk which surrounds the ear.&quot; [MaizeGDB:Clayton &amp; Renvoize ref ID #, MaizeGDB:lv (ID # 165572), http://www.harcourt.com/dictionary/def/4/9/6/3/4963600.html, MaizeGDB:kiesselbach (ID# 59445)]") :- x_cid(a65b125bd410af).
xc_microtheory(a65b125bd410af,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd410af,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
