'x_mo-definition'('x_ZEA--0015073',"&quot;A lateral branch (often referred to as an ear shoot) of the corn plant bears the female inflorescence (flowering system). Each lateral branch arises from the development of a lateral (axillary) bud, adjacent to one of the nodes of the culm. The lateral branch is subtended by a leaf. After pollination via the silks and fertilization of the ovule within each functionally female floret, the lateral branch develops into the typical ear. The lateral branch arises from the culm (main stem/stalk) at a node. The portion of the lateral branch below the 'ear' is called the shank. The axillary buds arising from nodes above the soil surface terminate in a pistillate inflorescence (ear). Usually all soon degenerate except the upper one or two located about midway up the culm. The amount of growth before disintegration (senescence) varies as the axillary buds may either die without much development or form 'ears' several centimeters long which resemble the functional ears, until they senesce.&quot; [MaizeGDB:232442, MaizeGDB:lv (ID # 165572), MaizeGDB:59445]") :- x_cid(a65b125bd410bd).
xc_microtheory(a65b125bd410bd,'x_zea_mays_anatomy-merged-SUMOMt').
xc_source_file(a65b125bd410bd,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/zea_mays_anatomy-merged-SUMO.kif').
